cd "G:/Android/AndroidStudioProjects/Taskbridge" && python - <<'EOF'
import sqlite3, sys, io
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8', errors='replace')
db = sqlite3.connect('file:data/taskbridge.db?mode=ro', uri=True)
cur = db.cursor()
# Крупнейшие таблицы и распределение events
print('=== event type distribution (top) ===')
try:
    rows = cur.execute("SELECT json_extract(payload,'$.type') AS t, COUNT(*) c FROM events GROUP BY t ORDER BY c DESC LIMIT 12").fetchall()
    for t, c in rows: print(t, c)
except Exception as e:
    print('json_extract err:', e)
print('=== avg payload size ===')
try:
    r = cur.execute("SELECT AVG(LENGTH(payload)), MAX(LENGTH(payload)) FROM events").fetchone()
    print('avg bytes:', round(r[0] or 0), 'max:', r[1])
except Exception as e: print(e)
print('=== biggest payloads ===')
try:
    rows = cur.execute("SELECT seq, json_extract(payload,'$.type'), LENGTH(payload) FROM events ORDER BY LENGTH(payload) DESC LIMIT 5").fetchall()
    for r in rows: print(r)
except Exception as e: print(e)
EOF

